#!/bin/sh
# Generated by build_installer.py; online and ZIP entrypoints are byte-identical.
set -eu
umask 077
base='https://github.com/shotlab/shotlab-cli/releases/download/installer-v1.6.0'
audience='public'
core_sha='0c8b2e11550314e6e1f0e52cf5a6c6db5367d1e9ab1df1a34fee8a6d8ef814ea'
node_version='24.22.0'
root="$HOME/.local/share/shotlab-installer"
runtime_lock=''
scratch=''
cleanup() {
  [ -z "$scratch" ] || rm -rf -- "$scratch"
  [ -z "$runtime_lock" ] || rmdir -- "$runtime_lock"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP
fail() { echo "Shotlab 安装停止：$*" >&2; exit 1; }
for dir in "$HOME/.local" "$HOME/.local/share" "$root" "$root/runtime"; do
  [ ! -L "$dir" ] || fail "安装目录不能是符号链接：$dir"
done
command -v curl >/dev/null 2>&1 || fail '需要 curl，请通过系统包管理器安装后重试。'
sha() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d ' ' -f 1
  elif command -v shasum >/dev/null 2>&1; then LC_ALL=C shasum -a 256 "$1" | cut -d ' ' -f 1
  else fail '需要 sha256sum 或 shasum 来校验下载'; fi
}
fetch() { curl --proto '=https' --proto-redir '=https' -fLsS --connect-timeout 30 --max-time 600 --retry 2 "$1" -o "$2"; }
scratch=$(mktemp -d "${TMPDIR:-/tmp}/shotlab-setup.XXXXXXXX")
core="$scratch/installer.mjs"
# $0 is a file when called from the ZIP; when piped to sh we use the pinned URL.
local_core=''
if [ -f "$0" ]; then local_core="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)/installer.mjs"; fi
if [ -n "$local_core" ] && [ -f "$local_core" ]; then cp "$local_core" "$core"

else fetch "$base/installer.mjs" "$core"; fi
[ "$(sha "$core")" = "$core_sha" ] || fail '共享安装逻辑 SHA-256 不一致；请重新下载引导包。'
node_bin=''
if command -v node >/dev/null 2>&1 &&
  node -e 'const [a,b]=process.versions.node.split(".").map(Number);process.exit(a>22||(a===22&&b>=20)?0:1)' >/dev/null 2>&1; then
  node_bin=$(command -v node)
fi
if [ -z "$node_bin" ]; then
  case "$(uname -s)/$(uname -m)" in
    Darwin/arm64) target=darwin-arm64; runtime_sha='6a9724d9b50a5f22b4816cded441b5a8d9ddae546191a5e5b7efa5a5e2ee26d5' ;;
    Darwin/x86_64) target=darwin-x64; runtime_sha='495e3f273c645f3c4677d438304cdfc701729ea5dec5728f5c8e76a2dece4b91' ;;
    Linux/aarch64|Linux/arm64) target=linux-arm64; runtime_sha='b7e7991d5407815adfa74a2a9cd4db683552c8ce32ff4a295c22e972849c3f5d' ;;
    Linux/x86_64) target=linux-x64; runtime_sha='28ea0a438de9a13bd7891fd758eee6c7819ee8af5442dfd8d45bd65e56d4228c' ;;
    *) fail '仅支持 macOS/Linux arm64、x86_64；Windows 请使用 install.ps1。' ;;
  esac
  runtime="$root/runtime/node-v$node_version-$target"
  [ ! -L "$runtime" ] || fail "运行时不能是符号链接：$runtime"
  mkdir -p "$root/runtime"
  if mkdir "$root/runtime/lock" 2>/dev/null; then runtime_lock="$root/runtime/lock"
  else fail "另一个运行时安装正在进行；确认没有安装进程后再清理 $root/runtime/lock"; fi
  if [ ! -e "$runtime" ]; then
    echo "安装专用 Node $node_version 运行时（不替换系统 Node）…"
    archive="node-v$node_version-$target.tar.gz"
    fetch "https://nodejs.org/dist/v$node_version/$archive" "$scratch/node.tar.gz"
    [ "$(sha "$scratch/node.tar.gz")" = "$runtime_sha" ] || fail 'Node SHA-256 校验失败'
    # This archive is authenticated against the pinned upstream checksum.
    tar -xzf "$scratch/node.tar.gz" -C "$scratch"
    mv "$scratch/node-v$node_version-$target" "$runtime"
  fi
  node_bin="$runtime/bin/node"
  [ -x "$node_bin" ] || fail "运行时不完整，请备份后移出 $runtime 并重试。"
  [ "$("$node_bin" --version)" = "v$node_version" ] || fail '专用运行时版本不一致'
  rmdir "$runtime_lock"; runtime_lock=''
  PATH="$runtime/bin:$PATH"; export PATH
fi
"$node_bin" "$core" "$@"
